def exit_code(value):
    if not re.fullmatch(rb"[0-9]+", value):
        raise ValueError(f"expected a numeric exit code, got {value!r}")
    code = int(value)
    if code > 255:
        raise ValueError(f"exit code must be between 0 and 255, got {code}")
    return code


def decode_payload(value):
    def decode(match):
        escape = match[1]
        if escape in ESCAPES:
            return ESCAPES[escape]
        if re.fullmatch(rb"x[0-9a-fA-F]{2}", escape):
            return bytes([int(escape[1:], 16)])
        raise ValueError(f"invalid escape {match[0]!r}")

    return re.sub(rb"\\(x[0-9a-fA-F]{2}|.)?", decode, value)


def load_case(directory):
    source = (directory / "source").read_bytes()
    compiler_exit = exit_code((directory / "exit_code").read_bytes().strip())
    inputs, outputs = [], [bytearray()]
    program_exit = None
    for number, line in enumerate((directory / "behaviour").read_bytes().split(b"\n"), 1):
        line = line.removesuffix(b"\r")
        if not line.strip() or line.lstrip().startswith(b"#"):
            continue
        command, _, payload = line.partition(b" ")
        try:
            if compiler_exit != 0:
                raise ValueError("behaviour must be empty when compilation is expected to fail")
            if program_exit is not None:
                raise ValueError("EXIT must be the last directive")
            if command == b"IN":
                value = decode_payload(payload)
                if b"\n" in value:
                    raise ValueError("IN supplies one line and cannot contain a newline")
                inputs.append(value)
                outputs.append(bytearray())
            elif command == b"OUT":
                outputs[-1].extend(decode_payload(payload))
            elif command == b"EXIT":
                program_exit = exit_code(payload.strip())
            else:
                raise ValueError(f"expected IN, OUT or EXIT, got {command!r}")
        except ValueError as error:
            raise ValueError(f"behaviour line {number}: {error}") from error
    if compiler_exit == 0 and program_exit is None:
        raise ValueError("behaviour requires a final EXIT")
    return Case(source, compiler_exit, inputs, [bytes(output) for output in outputs], program_exit)


def resolve_interpreter(override, work_dir):
    if override is not None:
        return shutil.which(override)
    system, machine = platform.system().lower(), platform.machine().lower()
    machine = {"amd64": "x86_64", "arm64": "aarch64"}.get(machine, machine)
    if system == "windows" and machine in ("x86_64", "aarch64"):
        bundled = INTERPRETERS / "ic26int-windows-x86_64.exe"
    else:
        bundled = INTERPRETERS / f"ic26int-{system}-{machine}"
    if not bundled.is_file():
        return shutil.which("ic26int")
    if os.access(bundled, os.X_OK):
        return str(bundled)
    # A checkout can lack Unix execute bits when binaries are added on Windows.
    executable = work_dir / bundled.name
    shutil.copyfile(bundled, executable)
    executable.chmod(0o700)
    return str(executable)


