# // Changes: Allow snapshot runs to skip Valgrind origin tracking.
def valgrind_command(command, valgrind, log, *, origins=True):
    if valgrind is None:
        return command
    log.unlink(missing_ok=True)
    flags = [flag for flag in VALGRIND_FLAGS if not flag.startswith("--error-exitcode=")]
    # // AI generated by: Codex / gpt-6.2-sol
    # // Prompt: "During integration testing (b3c04bec9f058504622af1cf3350769d15f4168b) we realized, that memory tests were extremely slow. We fixed it. Read the fix and apply it to my current working directory. Change only the minimum required things, so keep for example the make test-memory command etc."
    # // Changes: Origin bookkeeping is diagnostic-only; undefined-value detection remains enabled.
    if not origins:
        flags = [flag for flag in flags if not flag.startswith("--track-origins=")]
        flags.append("--track-origins=no")
    return [valgrind, *flags, f"--error-exitcode={VALGRIND_ERROR}", f"--log-file={log}", *command]


def valgrind_error(valgrind, log, code):
    if valgrind is None:
        return None
    leaked, detail = parse_valgrind_log(log)
    if leaked is None:
        return f"Valgrind: {detail}"
    if leaked:
        return f"Valgrind found {leaked} leaked or reachable bytes ({' '.join(detail.splitlines())})"
    if code == VALGRIND_ERROR:
        return "Valgrind reported memory errors"
    return None


def compile_source(command, source, timeout, log_base):
    stdout_path = log_base.with_suffix(".stdout.log")
    stderr_path = log_base.with_suffix(".stderr.log")
    with stdout_path.open("wb") as stdout, stderr_path.open("wb") as stderr:
        start = perf_counter()
        run = subprocess.run(command, input=source, stdout=stdout, stderr=stderr, timeout=timeout)
        elapsed_ms = (perf_counter() - start) * 1000
    run.stdout = stdout_path.read_bytes()
    run.stderr = stderr_path.read_bytes()
    return run, elapsed_ms


def describe_exit(code):
    crash = _crash_name(code)
    return f"crashed ({crash})" if crash else f"exited with code {code}"


def preview(value):
    return repr(value[:160]) + ("..." if len(value) > 160 else "")


def check_behaviour(case, code, actual_outputs):
    for index, (expected, actual) in enumerate(zip(case.outputs, actual_outputs)):
        context = f"after reading input {preview(case.inputs[index - 1])}" if index else "at startup"
        boundary = (
            f"before reading input {preview(case.inputs[index])}"
            if index < len(case.inputs) else "before exiting"
        )
        if actual != expected:
            ending = f"; program {describe_exit(code)}" if index == len(actual_outputs) - 1 else ""
            return f"{context}, expected output {preview(expected)} {boundary}, got {preview(actual)}{ending}"
    actual_reads = len(actual_outputs) - 1
    if actual_reads < len(case.inputs):
        return f"expected input request for {preview(case.inputs[actual_reads])}, but program {describe_exit(code)}"
    if actual_reads > len(case.inputs):
        return f"unexpected input request #{len(case.inputs) + 1}"
    if code != case.program_exit:
        return f"expected program exit code {case.program_exit}, but it {describe_exit(code)}"
    return None


