def gain(before, after):
    if before is None or after is None or before == 0:
        return None
    return 100 * (before - after) / before


def gains(results):
    before, after = results
    if before.error or after.error:
        return (None,) * len(METRICS)
    return tuple(gain(old, new) for old, new in zip(before.metrics(), after.metrics()))


def value_text(value):
    if value is None:
        return "n/a"
    return f"{value:.3f}" if isinstance(value, float) else str(value)


def gain_text(value):
    return "n/a" if value is None else f"{value:+.2f}%"


def summary(results, valgrind):
    lines = ["IFJ26 e2e summary", f"Valgrind {'enabled' if valgrind else 'disabled'}"]
    for index, (mode, _, _) in enumerate(MODES):
        failed = sum(pair[index].error is not None for pair in results.values())
        lines.append(f"{mode}: {len(results) - failed} passed, {failed} failed")
    lines.append("Average gain across passing pairs (positive is an improvement)")
    for index, metric in enumerate(METRICS):
        values = [gains(pair)[index] for pair in results.values()]
        available = [value for value in values if value is not None]
        lines.append(f"  {metric}: {gain_text(mean(available) if available else None)} ({len(available)} pairs)")
    for name, pair in results.items():
        lines.extend(("", name))
        for (mode, _, _), result in zip(MODES, pair):
            status = f"FAIL: {result.error}" if result.error else "PASS"
            lines.append(f"  {mode}: {status}")
            if result.log_dir is not None:
                lines.append(f"    logs: {result.log_dir}")
            for metric, value in zip(METRICS, result.metrics()):
                lines.append(f"    {metric}: {value_text(value)}")
        lines.append("  Gain: " + ", ".join(
            f"{metric} {gain_text(value)}" for metric, value in zip(METRICS, gains(pair))
        ))
    return "\n".join(lines) + "\n"


def display_path(path):
    path = path.resolve()
    cwd = Path.cwd()
    if path.is_relative_to(cwd):
        path = path.relative_to(cwd)
    return path.as_posix()


