# // Changes: Run the fork driver once and retain the existing per-allocation validation.
def driver_runs(driver, valgrind, timeout, log_dir):
    if not valgrind:
        raise ValueError("the memory driver requires Valgrind")
    command = valgrind_command(
        [driver, str(CASES / "everything" / "source"),
         str(log_dir.resolve()), str(math.ceil(timeout))],
        valgrind, log_dir / "driver-%p.valgrind.log", origins=False,
    )
    run = subprocess.run(command, capture_output=True)
    (log_dir / "driver.stderr.log").write_bytes(run.stderr)
    if run.returncode:
        raise ValueError(f"memory driver {describe_exit(run.returncode)}: {preview(run.stderr)}")
    records = []
    for expected, line in enumerate(run.stdout.splitlines(), 1):
        index, pid, code = map(int, line.split())
        if index != expected:
            raise ValueError("memory driver returned non-consecutive allocation indices")
        child_log = log_dir / f"driver-{pid}.valgrind.log"
        target = log_dir / f"malloc-{index}.valgrind.log"
        child_log.replace(target)
        records.append((index, code))
    parent_logs = list(log_dir.glob("driver-*.valgrind.log"))
    if len(parent_logs) != 1:
        raise ValueError("memory driver did not produce exactly one parent memory report")
    for parent_log in parent_logs:
        problem = valgrind_error(valgrind, parent_log, run.returncode)
        if problem:
            raise ValueError(f"memory driver: {problem}")
    if not records:
        raise ValueError("memory driver returned no allocation results")
    return iter(records)


